sealed class FlowWatchman(TimeProvider clock, TimeSpan grace) : BackgroundService {
    long _last = clock.GetTimestamp();                 // arrival: Interlocked.Exchange(ref _last, clock.GetTimestamp());
    protected override async Task ExecuteAsync(CancellationToken ct) {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(5));   // ticks do not overlap
        while (await timer.WaitForNextTickAsync(ct)) {
            var silent = clock.GetElapsedTime(Interlocked.Read(ref _last));
            if (silent > grace) Publish(subject, silent);   // health check / metric / alert sink
        }
    }
}
